TLM.f("Tempora/Pent09-2",{"officium":"Feria tertia infra Hebdomadam IX post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent09-0","from":{"Introitus":"Tempora/Pent09-0","Oratio":"Tempora/Pent09-0","Lectio":"Tempora/Pent09-0","Graduale":"Tempora/Pent09-0","Evangelium":"Tempora/Pent09-0","Offertorium":"Tempora/Pent09-0","Secreta":"Tempora/Pent09-0","Communio":"Tempora/Pent09-0","Postcommunio":"Tempora/Pent09-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 53:6-7"},{"k":"text","la":"Ecce, Deus adjuvat me, et Dóminus suscéptor est ánimæ meæ: avérte mala inimícis meis, et in veritáte tua dispérde illos, protéctor meus, Dómine."},{"k":"ref","la":"Ps 53:3"},{"k":"text","la":"Deus, in nómine tuo salvum me fac: et in virtúte tua libera me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ecce, Deus adjuvat me, et Dóminus suscéptor est ánimæ meæ: avérte mala inimícis meis, et in veritáte tua dispérde illos, protéctor meus, Dómine."}],"Oratio":[{"k":"text","la":"Páteant aures misericórdiæ tuæ, Dómine, précibus supplicántium: et, ut peténtibus desideráta concédas; fac eos quæ tibi sunt plácita, postuláre."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corinthios"},{"k":"ref","la":"1 Cor 10:6-13"},{"k":"text","la":"Fratres: Non simus concupiscéntes malórum, sicut et illi concupiérunt. Neque idolólatræ efficiámini, sicut quidam ex ipsis: quemádmodum scriptum est: Sedit pópulus manducáre et bíbere, et surrexérunt lúdere. Neque fornicémur, sicut quidam ex ipsis fornicáti sunt, et cecidérunt una die vigínti tria mília. Neque tentémus Christum, sicut quidam eórum tentavérunt, et a serpéntibus periérunt. Neque murmuravéritis, sicut quidam eórum murmuravérunt, et periérunt ab exterminatóre. Hæc autem ómnia in figúra contingébant illis: scripta sunt autem ad correptiónem nostram, in quos fines sæculórum devenérunt. Itaque qui se exístimat stare, vídeat ne cadat. Tentátio vos non apprehéndat, nisi humána: fidélis autem Deus est, qui non patiétur vos tentári supra id, quod potéstis, sed fáciet étiam cum tentatióne provéntum, ut póssitis sustinére."}],"Graduale":[{"k":"ref","la":"Ps 8:2"},{"k":"text","la":"Dómine, Dóminus noster, quam admirábile est nomen tuum in universa terra!"},{"k":"text","la":"Quóniam eleváta est magnificéntia tua super cœlos.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 58:2"},{"k":"text","la":"Eripe me de inimícis meis, Deus meus: et ab insurgéntibus in me líbera me. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 19:41-47"},{"k":"text","la":"In illo témpore: Cum appropinquáret Jesus Jerúsalem, videns civitátem, flevit super illam, dicens: Quia si cognovísses et tu, et quidem in hac die tua, quæ ad pacem tibi, nunc autem abscóndita sunt ab óculis tuis. Quia vénient dies in te: et circúmdabunt te inimíci tui vallo, et circúmdabunt te: et coangustábunt te úndique: et ad terram prostérnent te, et fílios tuos, qui in te sunt, et non relínquent in te lápidem super lápidem: eo quod non cognóveris tempus visitatiónis tuæ. Et ingréssus in templum, cœpit ejícere vendéntes in illo et eméntes, dicens illis: Scriptum est: Quia domus mea domus oratiónis est. Vos autem fecístis illam speluncam latrónum. Et erat docens cotídie in templo."}],"Offertorium":[{"k":"ref","la":"Ps 18:9, 10, 11, 12"},{"k":"text","la":"Justítiæ Dómini rectæ, lætificántes corda, et judícia ejus dulcióra super mel et favum: nam et servus tuus custódit ea."}],"Secreta":[{"k":"text","la":"Concéde nobis, quǽsumus, Dómine, hæc digne frequentáre mystéria: quia, quóties hujus hóstiæ commemorátio celebrátur, opus nostræ redemptiónis exercétur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 6:57"},{"k":"text","la":"Qui mandúcat meam carnem et bibit meum sánguinem, in me manet et ego in eo, dicit Dóminus."}],"Postcommunio":[{"k":"text","la":"Tui nobis, quǽsumus, Dómine, commúnio sacraménti, et purificatiónem cónferat, et tríbuat unitátem."},{"k":"macro","name":"Per Dominum"}]},"hr":{"bc3833977705a335":{"t":"Ps 53, 6-7, Ps 53, 3\n(Ps 53, 6-7) Evo Bog mi pomaže, Gospodin uzdržava moj život. Okreni zlo na moje protivnike i radi svoje vjernosti uništi ih, zaštitniče moj, Gospodine. (Ps 53, 3) Bože, po svojem imenu spasi me, i svojom me moću izbavi.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 53, 6-7) Evo Bog mi pomaže, Gospodin uzdržava moj život. Okreni zlo na moje protivnike i radi svoje vjernosti uništi ih, zaštitniče moj, Gospodine.","kn":"(Ps. 53, 6). Gle, Bog mi pomaže, Goapodin je branlć duše moje. Obrati zlo na neprijatelje moje, istinom -svojom rasprši ih, zaštitniče moj. Bože! (Ps. 53, 3) Bože, imenom svojim spasi me i krepošću svojom opravdaj me. Slava Ocu .... Gle, B og ...","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"e8e015c4be9cc178":{"t":"<i>Pomolimo se</i>.\nUši milosrđa tvoga, Gospodine, neka budu otvorene molbama onih koji ti se mole, i daj da od tebe ištu ono što je tebi ugodno da bi im željama udovoljio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka budu otvorene uši milosrđa Tvoga, Gospodine, prošnjama molbeb.ika,T da bi moliteljlma žuđeno poklonio, učini, da ištu, što je Tebiugodno, po G. n. >•","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"0ea7ea7133037846":{"t":"1 Kor 10, 6-13\nČitanje Poslanice bl. Pavla apostola Korinćanima. Braćo, ne želimo zla kao što su oni željeli. Ne budite idolopoklonici kao neki od njih, kao što je pisano: Narod sjede da jede i pije, pa ustaše da igraju. Ne griješimo bludno kao što su griješili neki od njih, i pade ih u jedan dan dvadeset i tri tisuće. Ne iskušavajmo Krista kao što su ga iskušavali neki od njih, te su izginuli od zmija. Ne mrmljajte kao što su mrmljali neki od njih, te su poginuli od zatirača. Ovo se sve dogodilo njima kao slika, a napisano je za opomenu nama, koji smo doživjeli posljednja vremena. Tko misli da stoji, neka pazi da ne padne. Zahvatila nas je samo ljudska kušnja, jer Bog je vjeran i ne dopušta da budete kušani više nego što možete podnijeti. A da biste mogli podnijeti, učinit će kušnji kraj.","kn":"Čitanje poslanice bi. Pavla apostola Korlnćanima (I, 10, 6-13)j Braćol Ne želimo zala, kao što su željeli oni. Ne budite idolopoklonici kao neki od njih, kako je pisano: Sjede narod da jede i pije, i ustanu da igraju. I ,ne griješimo bludno, kao što su neki od njih griješili i u jedan ih dan padne dvadeset i tri tisuće. I ne iskušavajmo Krista kao što su iskušavali neki od njih, te su izginuli od zmija. Ne mrmljajte, kao što su mrmljali neki od njih, pa su izginuli od žatirača. Sve se ovo njima događalo u slici, a ipisano je za opomenu nama, kojima je došao svršetak vremena. Tko' misli, da stoji, neika pazi, da ne padne. Samo čovječja kušnja vas je zahvatila, jer Bog je vjeran, i ne do- pušta, da budete kušani y;iše, nego. možete, a da biste mogli podnesti, učinit će kraj. kušnji.","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"3896297bbf67bdd8":{"t":"Ps 8, 2\nGospodine, Gospodine naš, kako je divno ime tvoje po svoj zemlji. Veličanstvo je tvoje uzdignuto nad nebesa.\n\nPs 58, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nIzbavi me od neprijatelja mojih, Bože moj, i od onih koji ustaju na me oslobodi me. <i>Aleluja</i>.","kn":"(Ps. 8, 21. Gospodine, .Gospodine -naš, kako je divno ime Tvoje po svoj zemlji! Jer se podigla slava Tvoja više nebesa. Alelu,i'a, aleluja.\n\n(Ps. 58, 2) Izbavi me od neprijatelja mojih. Bože moj, i o:slobodi me od onih, koji ustaju na me, -aleluja.","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"34a6307bf7cae52f":{"t":"Lk 19, 41-47\nSlijedi sveto Evanđelje po Luki. U ono vrijeme kad se Isus približio Jeruzalemu, ugleda grad i zaplaka nad njim govoreći: O kad bi i ti znao, i to u ovaj dan što ti donosi mir! Ali je sada sakriveno tvojim očima. Doći će dani, kada će te tvoji neprijatelji okružiti opkopom, opkolit će te i pritisnuti sa svih strana. Satrt će tebe i tvoju djecu u tebi i neće u tebi ostaviti ni kamena na kamenu, jer nisi spoznao vremena svojega pohoda! A kad uđe u hram, stade izgoniti iz hrama prodavače i kupce, i reče im: Pisano je: Moj dom, dom je molitve, a vi ste ga pretvorili u razbojničku spilju. I svaki je dan naučavao u hramu.","kn":"t Slijedi sveto evanđelje po Luki (19, 41-47). U ono vrije-me, kad se Isus približio Jeruzalemu, ugleda grad i zaplače nad njim: O, kad bi ti znaoi to baš u ovaj dan, što je za : tvoj mir! Ali sada je sakriveno tvojim očima. Doci će: za. te dani, kada će te okružiti tvoji neprijatelji -opkoippm, i opkOil.it će te i pritisnuti sa svih strana. Satrt će tebe i tvoju djecu, koja su u tebi, i ne će u tebi ostaviti - ni kamena na kamenu, jer .mijesi, poznao vremena svoga pohoda. A -kad uđe u hram.,, poče izgoniti -one, koji su prodavali i kupovali j reče im:. Pisano je: Kuća je moja kuća m-olitve, a vi ste. jb učinili razbojničk-o-'m špiljom. I svaki Je da-n učio u hramu. ' .","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"abdab28d88e9b4d3":{"t":"Ps 18, 9 i 10 i 11 i 12\nNaredbe su Gospodnje ispravne, one razveseljuju srca. I sudovi su njegovi slađi od meda i saća, pa sluga tvoj pazi na njih.","kn":"(Ps. 18, 9-12). Zapovijedi su Gospodnje pravedne, one Vesele srca, i sudovi njegovi šlađi -od međa i saća, zato ih i sluga Tvoj čuva.","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"401819b2f8ea96a5":{"t":"Podaj nam, molimo, Gospodine, da dostojno pribivamo ovim otajstvima, jer se vrši djelo našeg otkupljenja kad god se slavi spomen ove žrtve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj nam, mo-limo. Gospodine, da đos-tojno izvršujemo ova otajstva; jer’ kadgod se slavi spomen ove. žrtve,, izvršava se djelo našega -otkupljenja, po G,. n.","knRef":"Kniewald 1942, str. 388–389 (snimka 195) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"82267e0674fb3372":{"t":"Iv 6, 57\nTko jede moje tijelo i pije moju krv ostaje u meni i ja u njemu, kaže Gospodin.","kn":"(Iv. 6, 57). Tko blaguje tijelo moje i pije krv moju, u meni ostaje i ja u njemu, veli Gospodin.","knRef":"Kniewald 1942, str. 140–141 (snimka 71) (OCR)"},"1bccaaa295b13727":{"t":"<i>Pomolimo se</i>.\nSjedinjenje u tvojem otajstvu, molimo, Gospodine, da nas očisti i poda nam jedinstvo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pričeščenje Tvoje tajne, molimo Gospodine, da nam udijeli očišćenje i poda jedinstvo, po G. n.","knRef":"Kniewald 1942, str. 390–391 (snimka 196) (OCR)"}}});
